  ('ng-eht27-echelon-hovertank', 'Rooftop Grenade Launcher (1, top of crew compartment)', 25, 'Small target: Called Shot, -3 to strike.', 2),
  ('ng-eht27-echelon-hovertank', 'Undercarriage Hover Jets (6)', 80, 'Each. Small target: Called Shot, -3 to strike.', 3),
