INSERT OR IGNORE INTO vehicle_weapons (vehicle_slug, ordinal, name, damage, is_mega_damage, range, rate_of_fire, payload, bonus, note) VALUES
  ('ng-bad202-badger', 1, 'NG-BAD202 Ion Cannon', '6D6 M.D. per blast', 1, '4,000 ft (1,219 m)', 'Each blast counts as one melee attack', 'Effectively unlimited', NULL, 'A new, somewhat experimental design in the top turret, turning 360 degrees with a 30 degree up and down arc. Its own gunner works it from the crew compartment, not the turret; the pilot or co-pilot can fire it in a pinch. Anti-armor and anti-robot; anti-monster and assault.'),
  ('ng-bad202-badger', 2, 'NG-BAD203 Rail Gun', '1D4x10 M.D. per 40-round burst; special anti-supernatural rounds may be loaded where they apply', 1, '4,000 ft (1,219 m)', 'Each burst counts as one melee attack', '3,680 rounds (92 bursts), in two detachable drums of 1,840 rounds (46 bursts) each, reached from the sides', NULL, 'Forward-facing nose gun with a dedicated gunner; the page gives its traverse as 20 degrees in any direction and again as 30 degrees side to side and up and down. Anti-personnel and assault; defense and anti-armor.'),
  ('ng-bad202-badger', 3, 'NG-BAD204 Mini-Missile Box Launcher', 'By mini-missile type; the standard load is 60% high explosive (1D4x10 M.D.), 30% plasma (1D6x10 M.D.) and 10% smoke', 1, 'By missile type', 'One at a time or in volleys of 2, 4 or 6; each launch counts as one melee attack', '42 mini-missiles', NULL, 'Beside the rail gun on the passenger side; an armoured lid drops to fire and closes again over the remaining missiles. Takes any mini-missile. Anti-missile and anti-armor; anti-monster and defense.'),
  ('ng-bad202-badger', 4, 'Gunners'' Nest (top)', 'By the shooters'' own weapons', 0, NULL, NULL, NULL, NULL, 'Ten long gun slits on the upper deck, each with a pull-down chair steady enough for Aimed or Called Shots while the Badger is stopped or doing 20 mph (32 km) or less. A second shooter can kneel or crouch at a slit, at -1 to strike for both. From a fast-moving Badger, shooting counts as shooting wild, with no strike bonuses.'),
  ('ng-rsv7a-centipede', 1, 'CP-107 Plasma Cannon', '1D6x10 M.D. per blast', 1, '2,000 ft (610 m)', 'Each blast counts as one melee attack', 'Effectively unlimited', NULL, 'Forward-facing main gun turning 30 degrees to either side, 20 degrees down and 45 up; its gunner sits in the crew compartment to the right of and below it. Anti-armor; anti-monster, anti-infantry and assault.'),
  ('ng-rsv7a-centipede', 2, 'Medium-Range Box Launcher', 'By missile type; standard issue is armor piercing (2D4x10 M.D.) or high explosive (2D6x10 M.D.)', 1, 'Usually about 40 miles (64 km)', 'One at a time or in volleys of 2, 3 or 4', 'Nine medium-range missiles', '+1 to strike (guided missiles)', 'On the left, atop the forward passenger compartment; swings up through 180 degrees to fire behind or at flyers. Fired by the gunner or pilot. Anti-aircraft and anti-armor; defense.'),
  ('ng-rsv7a-centipede', 3, 'Short-Range Missile Launchers', 'By missile type, typically fragmentation 2D4x10 M.D. to a 20 ft (6.1 m) radius, high explosive 2D6x10 M.D. to 15 ft (4.6 m), armor piercing 2D6x10 M.D. to 5 ft (1.5 m), or plasma 2D6x10 M.D. to 15 ft (4.6 m)', 1, 'Typically 5 miles (8 km); plasma and fragmentation missiles reach only 3 miles (4.8 km)', 'One at a time or in volleys of 2 or 4', 'Six, one per tube', NULL, 'Six tubes on the head, three a side behind the operator''s cockpit; fired by the pilot or co-pilot. Anti-armor and anti-fortification; anti-monster and assault.'),
  ('ng-rsv7a-centipede', 4, 'Side Mini-Missile Launchers (2)', 'By missile type; usually high explosive (1D4x10 M.D.) or plasma (1D6x10 M.D.)', 1, 'One mile (1.6 km)', 'One at a time or in volleys of 2 or 3', '28, 14 per launcher', NULL, 'A box launcher on each side of the front section. Anti-armor and anti-missile; defense.'),
  ('ng-rsv7a-centipede', 5, 'Laser Tool Turrets (2)', 'Five settings: 1D6x10 S.D.C., 1D6 M.D., 2D6 M.D., 4D6 M.D. or 1D4x10 M.D.', 1, '100 ft (30.5 m)', 'Each blast counts as one melee attack', 'Effectively unlimited', NULL, 'Cutting and welding tools flanking the head, so the range is short; each turns 360 degrees with a 45 degree up and down arc, with an 800 ft (244 m) spotlight under the barrels. Welding and cutting; defense.'),
  ('ng-rsv7a-centipede', 6, 'Robot Mandibles', 'Crush 3D6 M.D. per squeeze; the head''s built-in tools do at most 2D4 M.D.', 1, 'The tools reach 10 ft (3 m) or need the target held in the mandibles', NULL, NULL, NULL, 'The mandibles grab, hold and crush, but are not built to fight: no combat bonuses (unmodified strike and dodge rolls), and no punch or power punch.'),
  ('ng-eht27-echelon-hovertank', 1, 'NG-EHT227 Dual Ion and Rail Cannon', 'Rail gun 2D4x10 M.D. per 80-round burst, or ion blast 1D4x10 M.D.; one or the other each attack, never both', 1, '4,000 ft (1,219 m) for both', 'Each blast counts as one melee attack', 'Ion cannon unlimited; 8,000 rail gun rounds (100 bursts)', NULL, 'Over-and-under mount, the larger rail barrel on top hitting harder than high explosive shells with a simple feed that keeps the crew small. Faces forward with a 45 degree up and down arc. Anti-armor and anti-robot; anti-monster and anti-fortification.'),
  ('ng-eht27-echelon-hovertank', 2, 'NG-EHT127 Grenade Launcher', 'By grenade: fragmentation 3D6 M.D. to a 12 ft (3.7 m) area; high explosive/armor piercing 4D6 M.D. to a 3 ft (0.9 m) radius; plasma 6D6 M.D. to a 5 ft (1.5 m) radius; Hex anti-monster grenades (see the Forester power armor, p.98); smoke fills a 40 ft (12.2 m) radius; tear gas covers a 25 ft (7.6 m) radius; stun/flash', 1, '1,000 ft (305 m)', 'Each shot counts as one melee attack', '60-round drum, with two spare drums carried inside', NULL, 'Roof mount atop the crew compartment, turning 45 degrees to either side with a 20 degree up and down arc; combat grenades, or smoke and tear gas for riot work. Tear gas: anyone lacking a gas mask or environmental armor suffers -10 to strike, parry and dodge, -3 initiative and one fewer melee attack inside the cloud, lasting 1D6+1 melee rounds after leaving it. Stun/flash: -10 to strike, parry and dodge, -1 initiative and one fewer melee attack, for 1D4 melee rounds. Anti-personnel and assault; riot control and defense.');

-- Read the result back. This script asserts its OWN rows and nothing else.
SELECT 'all 3 machines are in' AS assertion, count(*) AS got, 3 AS want
  FROM vehicles WHERE slug IN ('ng-bad202-badger', 'ng-rsv7a-centipede', 'ng-eht27-echelon-hovertank');
SELECT 'their 52 locations are in' AS assertion, count(*) AS got, 52 AS want
  FROM vehicle_locations WHERE vehicle_slug IN ('ng-bad202-badger', 'ng-rsv7a-centipede', 'ng-eht27-echelon-hovertank');
SELECT 'their 12 weapon entries are in' AS assertion, count(*) AS got, 12 AS want
  FROM vehicle_weapons WHERE vehicle_slug IN ('ng-bad202-badger', 'ng-rsv7a-centipede', 'ng-eht27-echelon-hovertank');
SELECT 'each main body location equals mdc_main_body' AS assertion, count(*) AS got, 0 AS want
  FROM vehicles v JOIN vehicle_locations l ON l.vehicle_slug = v.slug AND l.location = 'Main Body'
  WHERE v.slug IN ('ng-bad202-badger', 'ng-rsv7a-centipede', 'ng-eht27-echelon-hovertank') AND l.mdc IS NOT NULL AND v.mdc_main_body IS NOT NULL AND l.mdc <> v.mdc_main_body;

